#define LPUART_BASE_ADDRS                     { LPUART_0_BASE, LPUART_1_BASE, LPUART_2_BASE, LPUART_3_BASE, LPUART_4_BASE, LPUART_5_BASE, LPUART_6_BASE, LPUART_7_BASE }
